// Runtime translation lookup. Source-of-truth English is in
// `sourceCatalog.ts`; this file holds the 6 translated languages.
//
// Update flow: when adding/changing a key:
//   1. Edit `sourceCatalog.ts` (English + context note).
//   2. Run the translation agent(s) on the updated catalog.
//   3. Paste outputs into the corresponding language map below.
//
// `useT` reads from here; missing keys fall back to the English source
// catalog so the UI never shows raw `key.path` to the user.
//
// Initial population: two independent translator agents produced parallel
// drafts; this file is the reconciled merge favouring (a) authentic
// devotional/Christian vocabulary per language, (b) concise button labels,
// (c) internal consistency (e.g. "Bible versions" wording matches between
// the sheet header and the Account row), and (d) accurate placeholder
// preservation.

