    'help.q.reminderSettings': '設定或更改每日提醒時間',
    'help.a.gettingStarted.p1': '打開「禱告」分頁，點選「開始禱告」。你會依序經歷一段經文、一段默想、一個行動建議，以及一段引導禱告。結束時點選「阿們」即可完成。',
    'help.a.gettingStarted.p2': '晨禱在下午 6 點前開放，晚禱在下午 6 點後開放。兩次都完成後，你會在連續天數上看到今天的火焰亮起。',
    'help.a.notesAndBookmarks.p1': '閱讀時儲存的內容都在「我的」→「我的記錄」裡。點選任一卡片可看到完整清單：',
    'help.a.notesAndBookmarks.b1': '筆記 —— 打開一節經文，點選「筆記」，寫下你的默想。',
    'help.a.notesAndBookmarks.b2': '書籤 —— 點選章節標題旁的書籤圖示。',
    'help.a.notesAndBookmarks.b3': '標註 —— 點選一節經文，選一個顏色圓點。',
    'help.a.notesAndBookmarks.p2': '點選任何已儲存的書籤或標註，即可在「聖經」分頁直接跳回該節。',
    'help.a.shareVerse.p1': '閱讀時點選一節經文以開啟工具列，再點選「分享」。從三種模板（方形、直式、限時動態）中選一種，再選擇 Facebook、WhatsApp 或 Instagram。',
    'help.a.shareVerse.p2': '我們會即時以你目前的語言產生圖片，並交給你選擇的應用程式。',
    'help.a.removeAds.p1': '前往「我的」→「移除廣告」。共有三種方案，價格皆由 Google Play 以當地貨幣計算：',
    'help.a.removeAds.b1': '終身 —— 一次付清，不再扣款。',
    'help.a.removeAds.b2': '年度 —— 自動續訂的年訂閱。',
    'help.a.removeAds.b3': '每月 —— 自動續訂的月訂閱。',
    'help.a.removeAds.h2': '付費後還是看到廣告？',
    'help.a.removeAds.p2': '打開同一個「移除廣告」頁面，點選「恢復購買」。請確認你登入的是當時付款的 Google 帳號。同步通常在一分鐘內完成。',
    'help.a.cancelSubscription.p1': '訂閱由 Google Play 管理，而非應用程式本身。打開 Play 商店 →點選你的頭像 →「付款與訂閱」→「訂閱」，選擇 Her Bible，再點選「取消」。',
    'help.a.cancelSubscription.p2': '在目前的計費週期結束前，你仍享有無廣告體驗。',
    'help.a.switchVersion.p1': '打開「我的」→「帳戶」→「聖經譯本」。選一個譯本下載一次，之後即可完全離線閱讀。只有完整下載的譯本才能設為目前譯本。',
    'help.a.reminderSettings.p1': '完成一次禱告後會出現提醒設定頁 —— 點選「設定時間」，選擇你希望每天收到提醒的時間。',
    'help.a.reminderSettings.p2': '你也可以隨時在手機系統的「設定」→「通知」→「Her Bible」中更改時間或關閉提醒。',
