    'streak.info.title': 'Warum Serien?',
    'streak.info.body1': 'Deine Beziehung zu Gott ist mehr als eine Zahl, aber lass deine Serie dich einfach daran erinnern, dich täglich mit Gott und seinem Wort zu verbinden.',
    'streak.info.body2': 'Serien sind sanfte Erinnerungen, kein Maßstab deines Glaubens. Einen Tag verpasst? Morgen ist ein neues Blatt – komm wieder, und deine Serie beginnt zu wachsen.',
