    'reflections.empty.hint': 'Tippe nach deinem Morgen- oder Abendgebet auf „Betrachtung schreiben“ – was du speicherst, erscheint hier.',
    'addWidget.title': 'Bring sein Wort auf\ndeinen Startbildschirm',
    'addWidget.body': 'Täglicher Vers + dein nächstes Gebet, einen Fingertipp entfernt. Wähle unten eine Größe – du kannst sie später jederzeit ändern.',
